// Byte-identical parity: for every fixture, the TypeScript scanner must produce
// the same canonical JSON report as the Python package. The fixtures and their
// golden reports are generated by test/gen_fixtures.py.
import { readFileSync, readdirSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";
import { describe, expect, it } from "vitest";
import { scan } from "../src/report.js";
import { canon } from "../src/canon.js";

const FIX = join(dirname(fileURLToPath(import.meta.url)), "..", "fixtures");

const names = readdirSync(FIX)
  .filter((f) => f.endsWith(".safetensors"))
  .map((f) => f.replace(/\.safetensors$/, ""));

describe("Python/TypeScript report parity", () => {
  it("has fixtures to check", () => expect(names.length).toBeGreaterThan(0));

  for (const name of names) {
    it(name, async () => {
      const bytes = new Uint8Array(readFileSync(join(FIX, `${name}.safetensors`)));
      const golden = readFileSync(join(FIX, `${name}.json`), "utf-8").trimEnd();
      const rep = await scan(bytes);
      rep.file = `${name}.safetensors`; // Python uses the file name
      expect(canon(rep)).toEqual(golden);
    });
  }
});
